def head(title):return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="review.css"><title>{title}</title></head><body><header><a href="index.html">PLAYGRID</a><span>Issue #61 · design review only</span></header>'
def card(c):return f'<article class="face-card"><img src="avatar-studio/{c["preview"]}" alt="{c["name"]}"><strong>{c["name"]}</strong><small>{c["silhouette"]}</small><div class="tiny">'+''.join(f'<img src="avatar-studio/assets/thumbnails/{c["id"]}-{n}.png" width="{n}" height="{n}" alt="{c["name"]} at {n} pixels">' for n in [24,32,48])+'</div></article>'
(P/'characters.html').write_text(head('32 additions · 3 home foundations')+'<main><h1>The same family. More individual faces.</h1><p>32 additional characters refined from Issue #58; 3 editable studies of the unchanged home crew. Palettes and accessories are not counted as new characters.</p><div class="hero"><img src="../../node-server/public/assets/hero-mascots.png" alt="Exact unchanged canonical Playgrid home artwork"><div><h2>The three home foundations.</h2><div class="foundations">'+''.join(card(c) for c in C if not c['isAdditional'])+'</div></div></div><p class="note">Review difference: editable vector rendering is cleaner than the painted home artwork. Pose/texture are not pixel-identical. The canonical raster stays untouched. Tiny sizes below are real 24/32/48px exports.</p><h2>The 32 additional bases.</h2><div class="grid">'+''.join(card(c) for c in C if c['isAdditional'])+'</div></main></body></html>')
(P/'style-delta.html').write_text(head('Matching-config style delta')+'<main><h1>A targeted refinement, not another character reset.</h1><p>Same base IDs, default pose, no hats/glasses/accessories, same accent palette. Left: original Issue #58 SVG. Right: Issue #61 preferred-look SVG. Juniper’s expression, Maple’s short dog ears and Bandit’s round raccoon ears show the new delta without relying on recolors.</p><div class="delta-grid">'+''.join(f'<article class="delta-card"><h2>{c["name"]}</h2><div class="delta-pair"><div><img src="reference/{c["id"]}-issue58.svg" alt="Issue 58 {c["name"]}"><span>Issue #58</span></div><div><img src="avatar-studio/{c["preview"]}" alt="Issue 61 {c["name"]}"><span>Issue #61 · same ID</span></div></div></article>' for c in C if c['id'] in ['a02','a13','a19'])+'</div><p class="note">Existing avatars and original home art are preserved. This sheet shows a refinement of previously authored bases, not three newly counted characters.</p></main></body></html>')
def person(cid,name,sub,right,size=32):return f'<div class="person"><img src="avatar-studio/assets/thumbnails/{cid}-{size}.png" width="{size}" height="{size}" alt="{name} avatar"><span><b>{name}</b><small>{sub}</small></span><span class="right">{right}</span></div>'
(P/'contexts.html').write_text(head('Avatar identity in context')+'<main><h1>A player you recognize everywhere.</h1><p>Static identity-context studies. Actual app navigation, scores and readiness remain unchanged. No new game layouts are proposed here.</p><div class="context-grid"><section class="context"><h2>Shared lobby · 32px identities</h2><div class="people">'+person('h01','Alex','You · Host','Ready')+person('a17','Nova','In the party','Ready')+person('a22','Kai','Choosing a game','Not ready')+person('a14','Mia','In the party','Ready')+'</div><footer>Names, silhouette and readable status stay visible.</footer></section><section class="context"><h2>Scoreboard · 48px result faces</h2><div class="people">'+person('h03','Trouble','1st place','1,200 pts',48)+person('a05','Mira','2nd place','980 pts',48)+person('a24','Halo','3rd place','840 pts',48)+'</div><footer>Result effects never cover ranks or player names.</footer></section><section class="context"><h2>Waiting room · 24px compact rows</h2><div class="people">'+person('a19','Bandit','Connected','Waiting',24)+person('a06','Rowan','Connected','Waiting',24)+person('h02','Home Robot','Connected','Ready',24)+'</div><footer>No continuous blinking across the whole list.</footer></section><section class="context"><h2>In game · 32px turn identity</h2><div class="turn-strip"><img src="avatar-studio/assets/thumbnails/h01-32.png" alt="Alex avatar"><strong>Alex</strong><span>Your shot · Solids</span></div><div class="mini-table">Approved board remains the focal point.</div><footer>Identity supports play; it does not become a dashboard.</footer></section></div></main></body></html>')
